using Builder.Core;
using System.Collections.Immutable;
using System.Security.Cryptography;
using System.Text.Json;

internal static class V1WorkflowChecks
{
    public static async Task Run(string root,string? evidenceRoot=null)
    {
        var output=evidenceRoot??Path.Combine(root,".local/evidence/v1-usability-20261022/core");Directory.CreateDirectory(output);var input=Path.Combine(root,".local/fixtures/distribution/distribution-assembly.3mf");var cases=new List<string>();var outputs=new List<object>();var realInput=Path.Combine(root,".local/evidence/v1-usability-20261022/inputs/prusa-mk3s/y-belt-holder.stl");var realParts=new List<object>();var repairInput=Path.Combine(root,"fixtures/generated/missing-top.stl");RepairComparison? repairComparison=null;
        void Pass(string name){cases.Add(name);Console.WriteLine("PASS "+name);}
        void Record(string path,string expected)=>outputs.Add(new{path=Path.GetFileName(path),sha256=Hash(path),expected});
        using(var session=new EditorSession())
        {
            Ok(session.Execute(new AddPrimitive(PrimitiveKind.Cube,new(12,14,6))));var existing=session.Snapshot.Scene.Objects.Single();Ok(session.UpdateModelMetadata(new("Mounting job",Description:"Destination information stays with the job"),session.Snapshot.Revision));Ok(await session.SaveAsync(Path.Combine(output,"before-insert.3mf")));Ok(session.Select(null));var before=session.Snapshot;
            Ok(await session.InsertAsync(input,expectedRevision:before.Revision));var inserted=session.Snapshot;var newIds=inserted.Scene.Objects.Where(o=>o.Id!=existing.Id).Select(o=>o.Id).ToImmutableArray();
            Check(newIds.Length==5&&inserted.Scene.Groups.Length==1,"Mixed-root fixture import shape changed.");
            Check(inserted.SelectedObjectIds.SequenceEqual(newIds),$"Insert selected {inserted.SelectedObjectIds.Length} of {newIds.Length} imported leaves; all independent roots and grouped members must be selected together.");
            Check(inserted.SelectedObjectId==newIds[0]&&inserted.EditingGroupId is null,"Insert primary/scope is not canonical.");Check(ReferenceEquals(inserted.Scene.Objects[0],existing)&&inserted.Scene.Metadata==before.Scene.Metadata&&inserted.FilePath==before.FilePath&&inserted.IsDirty,"Insert changed existing object, metadata or native path.");
            Ok(await session.PreviewTransformAsync(new MoveTransform(newIds[0],new(0,40,0)){ObjectIds=inserted.SelectedObjectIds}));var candidate=session.Snapshot.Preview!.Scene;foreach(var id in newIds){var a=inserted.Scene.Objects.Single(o=>o.Id==id);var b=candidate.Objects.Single(o=>o.Id==id);Near(b.Bounds.Center-a.Bounds.Center,new(0,40,0));Check(ReferenceEquals(a.Mesh,b.Mesh)&&ReferenceEquals(a.Material,b.Material),"Placement changed geometry/material ownership.");}Check(ReferenceEquals(candidate.Objects[0],existing),"Moving imported set moved original job part.");Apply(session);
            Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,inserted.Scene)&&session.Snapshot.SelectedObjectIds.SequenceEqual(newIds),"Undo placement did not restore imported set selection.");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene)&&session.Snapshot.SelectedObjectId==before.SelectedObjectId&&session.Snapshot.SelectedObjectIds.SequenceEqual(before.SelectedObjectIds)&&!session.Snapshot.IsDirty&&session.Snapshot.FilePath==before.FilePath,"One additional Undo did not restore exact pre-insert document/selection/path.");
            Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,inserted.Scene)&&session.Snapshot.SelectedObjectIds.SequenceEqual(newIds)&&session.Snapshot.SelectedObjectId==newIds[0],"Redo Insert lost selected imported roots.");Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,candidate),"Redo placement lost exact geometry.");
            var subset=Path.Combine(output,"inserted-parts.3mf");var exportBefore=session.Snapshot;Ok(await session.ExportSelectionAsync(subset,session.Snapshot.SelectedObjectIds));Same(session,exportBefore);using var subsetReader=new EditorSession();Ok(await subsetReader.OpenAsync(subset));Check(subsetReader.Snapshot.Scene.Objects.Length==5&&subsetReader.Snapshot.Scene.Groups.Length==1,"Selected export omitted independent inserted parts.");Record(subset,"All5 inserted leaves, including two independent anchors and3 Color trio members, translated together +40mmY; existing job part excluded");
            var native=Path.Combine(output,"assembled-job.3mf");Ok(await session.SaveAsync(native));using var reader=new EditorSession();Ok(await reader.OpenAsync(native));Check(reader.Snapshot.Scene.Objects.Length==6&&reader.Snapshot.Scene.Groups.Length==1&&reader.Snapshot.Scene.Metadata==before.Scene.Metadata,"Native roundtrip lost complete assembly or destination information.");Record(native,"Existing12x14x6 job part plus all5 imported colored leaves; one group, destination metadata retained");
        }
        Pass("Mixed-root Insert selects every imported independent leaf and whole group; immediate set placement, one-step Insert Undo/Redo, selected export and native reopen retain all parts/materials/path");
        using(var session=new EditorSession())
        {
            Ok(session.Execute(new AddCube()));var id=session.Snapshot.SelectedObjectId!.Value;Ok(await session.SaveAsync(Path.Combine(output,"preservation-baseline.3mf")));Ok(session.Execute(new RenameObject(id,"Temporary")));Ok(session.Undo());var before=session.Snapshot;Check(before.CanRedo&&!before.IsDirty,"Preservation baseline lacks clean Redo state.");
            Check((await session.InsertAsync(Path.Combine(output,"missing.3mf"))).Outcome==Outcome.Failed,"Missing import succeeded.");Same(session,before);
            foreach(var stage in new[]{"Reading model","Ready to insert"}){using var ct=new CancellationTokenSource();Check((await session.InsertAsync(input,cancellation:ct.Token,progress:new Progress(p=>{if(p.Stage==stage)ct.Cancel();}))).Outcome==Outcome.Cancelled,"Insert cancellation failed at "+stage);Same(session,before);}
            Check((await session.InsertAsync(input,expectedRevision:before.Revision-1)).Outcome==Outcome.Conflict,"Stale Insert succeeded.");Same(session,before);
            Ok(await session.PreviewMaterialAsync(new([id],new("Held paint",new(10,20,30)))));var held=session.Snapshot;Check((await session.InsertAsync(input)).Outcome==Outcome.Conflict,"Insert replaced held preview.");Same(session,held);Check(session.DiscardPreview(held.Preview!.Id).Outcome==Outcome.Cancelled,"Discard failed.");Same(session,before);
        }
        Pass("Missing/stale/cancelled imports and held-preview refusal preserve accepted scene, selection, native destination, clean state and Redo");
        using(var session=new EditorSession())
        {
            Ok(await session.OpenAsync(input));var group=session.Snapshot.Scene.Groups.Single();Ok(session.EnterGroup(group.Id,group.ObjectIds[0]));var before=session.Snapshot;Check((await session.InsertAsync(input)).Outcome==Outcome.Conflict,"Insert bypassed member editing guard.");Same(session,before);Ok(session.ExitGroup());
            var importedBefore=session.Snapshot;Ok(await session.InsertAsync(Path.Combine(root,"fixtures/generated/cube-20mm.stl"),ModelUnit.Millimeters));var selected=session.Snapshot;Check(selected.SelectedObjectIds.Length==1&&selected.SelectedObjectId==selected.Scene.Objects.Last().Id,"Single-object insertion selection regressed.");Check(selected.FilePath==importedBefore.FilePath,"Single-object insertion changed native destination.");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,importedBefore.Scene)&&session.Snapshot.SelectedObjectIds.SequenceEqual(importedBefore.SelectedObjectIds),"Single-object Insert Undo changed original selection.");
        }
        Pass("Member scope still refuses Insert safely; ordinary explicit-mm STL Insert keeps one new object selected and one-step Undo restores original scene selection");
        foreach(var partInfo in new[]{(Name:"y-belt-holder",Triangles:2472),(Name:"fan-shroud",Triangles:12588),(Name:"ir-sensor-cover-mmu2s",Triangles:664)})
        {
            using var session=new EditorSession();var realFile=Path.Combine(Path.GetDirectoryName(realInput)!,partInfo.Name+".stl");var empty=session.Snapshot;
            var strict=await session.OpenAsync(realFile,ModelUnit.Millimeters);Check(strict.Outcome==Outcome.Invalid&&strict.Message.Contains("Geometry only",StringComparison.OrdinalIgnoreCase),"Default Strict import did not retain actionable refusal.");Same(session,empty);
            Check((await session.OpenAsync(realFile,ModelUnit.Millimeters,stlMode:(StlImportMode)99)).Outcome==Outcome.Invalid,"Undefined Open STL mode accepted.");Same(session,empty);
            Check((await session.InsertAsync(realFile,ModelUnit.Millimeters,stlMode:(StlImportMode)99)).Outcome==Outcome.Invalid,"Undefined Insert STL mode accepted.");Same(session,empty);
            var opened=await session.OpenAsync(realFile,ModelUnit.Millimeters,stlMode:StlImportMode.GeometryOnly);Ok(opened);Check(opened.Message.Contains("attribute/color data was not imported",StringComparison.Ordinal),"Geometry-only import did not disclose omitted data.");var before=session.Snapshot;var part=before.Scene.Objects.Single();Check(part.Mesh.Triangles.Length==partInfo.Triangles&&part.Material is null&&part.TriangleMaterials.Count==0,"Geometry-only import interpreted colors or changed pinned faces.");
            var move=new MoveTransform(part.Id,new(12,-7,4));Ok(await session.PreviewTransformAsync(move));Check(session.DiscardPreview(session.Snapshot.Preview!.Id).Outcome==Outcome.Cancelled,"Real-part preview cancel failed.");Same(session,before);
            Ok(await session.PreviewTransformAsync(move));var moved=session.Snapshot.Preview!.Scene;Apply(session);Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene),"Real-part Undo lost original geometry.");Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,moved),"Real-part Redo changed mesh.");
            Ok(await session.PreviewArrangementAsync(new CenterOnPlateRequest([part.Id],true)));Apply(session);var onBed=session.Snapshot;var bounds=onBed.Scene.Bounds;Near(new(bounds.Center.X,bounds.Center.Y,bounds.Min.Z),new());Check(ReferenceEquals(onBed.Scene.Objects[0].Mesh,part.Mesh),"Real-part placement changed mesh/cavities.");
            var diagnosis=await session.DiagnoseAsync(part.Id,expectedRevision:onBed.Revision);Ok(diagnosis.Result);Same(session,onBed);Check(diagnosis.Diagnosis is not null,"Supported diagnosis returned no assessment.");
            var native=Path.Combine(output,"real-"+partInfo.Name+".3mf");Ok(await session.SaveAsync(native));var saved=session.Snapshot;var meshFile=Path.Combine(output,"real-"+partInfo.Name+".stl");Ok(await session.ExportStlAsync(meshFile));Same(session,saved);Record(native,"Pinned Prusa MK3S "+partInfo.Name+", "+partInfo.Triangles+" triangles; translation-only XYcentering and bed placement; editable native save");Record(meshFile,"Same accepted "+partInfo.Name+" world triangles, geometry-only millimeter STL; native path/history unaffected");
            foreach(var file in new[]{native,meshFile}){using var reader=new EditorSession();Ok(await reader.OpenAsync(file,ModelUnit.Millimeters));Check(reader.Snapshot.Scene.Objects.Length==1&&reader.Snapshot.Scene.TriangleCount==partInfo.Triangles,"Real-part reopen lost shells/faces.");Near(reader.Snapshot.Scene.Bounds.Min,bounds.Min);Near(reader.Snapshot.Scene.Bounds.Max,bounds.Max);}
            realParts.Add(new{path=realFile,sha256=Hash(realFile),stlMode=StlImportMode.GeometryOnly,unit=ModelUnit.Millimeters,diagnosis=diagnosis.Diagnosis,sourceBounds=before.Scene.Bounds,resultBounds=bounds});
            if(partInfo.Name=="y-belt-holder")
            {
                Check((await session.InsertAsync(realFile,ModelUnit.Millimeters)).Outcome==Outcome.Invalid,"Default Strict Insert silently dropped attributes.");Same(session,saved);
                using(var ct=new CancellationTokenSource()){Check((await session.InsertAsync(realFile,ModelUnit.Millimeters,cancellation:ct.Token,progress:new Progress(p=>{if(p.Stage=="Ready to insert")ct.Cancel();}),stlMode:StlImportMode.GeometryOnly)).Outcome==Outcome.Cancelled,"Geometry-only Insert cancel failed.");Same(session,saved);}
                var inserted=await session.InsertAsync(realFile,ModelUnit.Millimeters,stlMode:StlImportMode.GeometryOnly);Ok(inserted);Check(session.Snapshot.SelectedObjectIds.Length==1&&session.Snapshot.SelectedObjectId==session.Snapshot.Scene.Objects.Last().Id&&session.Snapshot.FilePath==saved.FilePath,"Geometry-only Insert selection/path failed.");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,saved.Scene)&&session.Snapshot.SelectedObjectIds.SequenceEqual(saved.SelectedObjectIds)&&!session.Snapshot.IsDirty,"Geometry-only Insert Undo lost clean saved work.");
            }
        }
        Pass("Three pinned real Prusa parts retain Strict default refusal, explicitly import geometry-only in mm, cancel/apply/Undo/Redo placement, diagnose and save/export/reopen3MF/STL; explicit-mode Insert remains safe");
        using(var session=new EditorSession(Path.Combine(root,"prototypes/Builder/Builder.GeometryWorker/bin/win-x64/Builder.GeometryWorker.exe")))
        {
            Ok(await session.OpenAsync(repairInput,ModelUnit.Millimeters));var before=session.Snapshot;var part=before.Scene.Objects.Single();
            var diagnosis=await session.DiagnoseAsync(part.Id,expectedRevision:before.Revision);Ok(diagnosis.Result);Check(diagnosis.Diagnosis is not null&&diagnosis.Diagnosis.Assessment.BoundaryEdges>0,"Missing-top fixture did not diagnose as open.");Same(session,before);
            var request=new RepairRequest(part.Id);Ok(await session.PreviewAsync(request));var first=session.Snapshot.Preview!;Check(first.Repair is not null&&first.Repair.After.BoundaryEdges==0,"Supported planar repair did not close the top.");Near(first.Scene.Bounds.Min,before.Scene.Bounds.Min);Near(first.Scene.Bounds.Max,before.Scene.Bounds.Max);Check(session.DiscardPreview(first.Id).Outcome==Outcome.Cancelled,"Repair preview Cancel failed.");Same(session,before);
            Ok(await session.PreviewAsync(request));var preview=session.Snapshot.Preview!;repairComparison=preview.Repair;var candidate=preview.Scene;Apply(session);Check(session.Snapshot.SelectedObjectId==part.Id&&session.Snapshot.IsDirty,"Repair Apply changed target identity or failed dirty state.");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene)&&session.Snapshot.SelectedObjectIds.SequenceEqual(before.SelectedObjectIds)&&!session.Snapshot.IsDirty,"Repair Undo lost exact original/open mesh selection.");Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,candidate),"Repair Redo regenerated accepted result.");
            var native=Path.Combine(output,"repaired-missing-top.3mf");Ok(await session.SaveAsync(native));var saved=session.Snapshot;var stl=Path.Combine(output,"repaired-missing-top.stl");Ok(await session.ExportStlAsync(stl));Same(session,saved);
            foreach(var file in new[]{native,stl})
            {
                using var reader=new EditorSession();Ok(await reader.OpenAsync(file,ModelUnit.Millimeters));Check(reader.Snapshot.Scene.Objects.Length==1&&reader.Snapshot.Scene.TriangleCount==candidate.TriangleCount,"Repair save/reopen lost result geometry.");Near(reader.Snapshot.Scene.Bounds.Min,candidate.Bounds.Min);Near(reader.Snapshot.Scene.Bounds.Max,candidate.Bounds.Max);var reopened=await reader.DiagnoseAsync(reader.Snapshot.SelectedObjectId!.Value);Ok(reopened.Result);Check(reopened.Diagnosis!.Assessment.BoundaryEdges==0,"Repair reopened with open edges.");
                outputs.Add(new{path=Path.GetFileName(file),sha256=Hash(file),expected="Supported planar top closure on existing synthetic20mm cube; one object, unchanged outer dimensions, closed boundary",bounds=candidate.Bounds,dimensionsMillimeters=candidate.Bounds.Size,triangles=candidate.TriangleCount});
            }
        }
        Pass("Damaged missing-top part diagnoses open, previews supported planar repair, cancels safely, applies with exact Undo/Redo and saves/exports/reopens closed3MF/STL at unchanged20mm dimensions");
        File.WriteAllText(Path.Combine(output,"v1-workflow-results.json"),JsonSerializer.Serialize(new{timestamp=DateTimeOffset.UtcNow,scenarioCount=cases.Count,cases,outputs,runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,core=new{path=typeof(EditorSession).Assembly.Location,sha256=Hash(typeof(EditorSession).Assembly.Location)},input=new{path=input,sha256=Hash(input)},repairJob=new{input=repairInput,sha256=Hash(repairInput),repairComparison},realParts,realPartProvenance=Path.Combine(Path.GetDirectoryName(realInput)!,"provenance.json"),realPartLicense=Path.Combine(Path.GetDirectoryName(realInput)!,"LICENSE"),limitations="Focused shared Core synthetic assembly insertion three pinned real-part geometry-only import/placement/save/export workflows, and one supported synthetic planar repair workflow. No general repair parity, full printability, font/nameplate or native UI behavior claim."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{cases.Count} V1 workflow groups passed. Evidence: {output}");
    }
    private static void Apply(EditorSession s)=>Ok(s.ApplyPreview(s.Snapshot.Preview!.Id));
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static void Ok(OperationResult result)=>Check(result.Succeeded,result.ToString());
    private static void Same(EditorSession s,EditorSnapshot before)=>Check(s.Snapshot==before,"Insert changed accepted/held preview state.");
    private static void Near(Vec3 a,Vec3 b)=>Check(Math.Abs(a.X-b.X)<.001&&Math.Abs(a.Y-b.Y)<.001&&Math.Abs(a.Z-b.Z)<.001,"Imported set placement differed.");
    private sealed class Progress(Action<OperationProgress> action):IProgress<OperationProgress>{public void Report(OperationProgress p)=>action(p);}
    private static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
}
